export type ParsedClaimPayoutInstruction<
  TProgram extends string = typeof HANSE_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    claimant: TAccountMetas[0];
    /**
     * Breakpoint pass gate (§2.10 amendment / §12): passes are verified
     * off-chain, so the gate sits at payout as the authority's co-signature.
     */
    authority: TAccountMetas[1];
    mutual: TAccountMetas[2];
    claim: TAccountMetas[3];
    /**
     * The mutual's rights authority over its pool — PDA ["mutual_auth",
     * mutual] under this program; signs both CPIs.
     * rights authority inside the CPIs.
     */
    rightsAuthority: TAccountMetas[4];
    /** own accounts inside both CPIs. */
    pool: TAccountMetas[5];
    /**
     * The claimant's pool position. CHECK: PDA ["depositor", pool, member]
     * under the pool program, verified in the handler; owner by the type.
     */
    depositor: TAccountMetas[6];
    /**
     * The pool treasury — payout source. CHECK: canonical pool ATA, verified
     * in the handler; the spend CPI re-checks mint/authority.
     */
    treasury: TAccountMetas[7];
    /** The claimant's canonical deposit-mint ATA — payout destination. */
    destination: TAccountMetas[8];
    depositMint: TAccountMetas[9];
    tokenProgram: TAccountMetas[10];
    poolProgram: TAccountMetas[11];
  };
  data: ClaimPayoutInstructionData;
};

export function parseClaimPayoutInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedClaimPayoutInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      claimant: getNextAccount(),
      authority: getNextAccount(),
      mutual: getNextAccount(),
      claim: getNextAccount(),
      rightsAuthority: getNextAccount(),
      pool: getNextAccount(),
      depositor: getNextAccount(),
      treasury: getNextAccount(),
      destination: getNextAccount(),
      depositMint: getNextAccount(),
      tokenProgram: getNextAccount(),
      poolProgram: getNextAccount(),
    },
    data: getClaimPayoutInstructionDataDecoder().decode(instruction.data),
  };
}
